import sys

def find_min(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        if nums[lo] < nums[hi]:
            return nums[lo]
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    return nums[lo]


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(find_min(nums))
